            fast = &fast.as_ref().unwrap().next.as_ref().unwrap().next;
            slow = &slow.as_ref().unwrap().next;
        }

        // Clone slow onwards and reverse second half
        let mut second_half = slow.clone();
        let mut prev: Option<Box<ListNode>> = None;

        while let Some(mut node) = second_half {
            let next = node.next.take();
            node.next = prev;
            prev = Some(node);
            second_half = next;
        }

        // Check palindrome
        let mut left = &head;
        let mut right = &prev;

        while let Some(r_node) = right {
            if let Some(l_node) = left {
                if l_node.val != r_node.val {
                    return false;
                }
                left = &l_node.next;
            }
            right = &r_node.next;
        }

        true
    }
}

